{"command":"cat <<'EOF' > src/config.rs
use std::env;
use std::ffi::OsString;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

pub fn get_effective_args() -> Vec<OsString> {
    let raw_args: Vec<OsString> = env::args_os().collect();

    // Check if --no-config is present
    let no_config = raw_args.iter().any(|arg| arg == "--no-config");

    if no_config {
        return raw_args;
    }

    if let Some(config_path) = env::var_os("RIPGREP_CONFIG_PATH") {
        if !config_path.is_empty() {
            let path = Path::new(&config_path);
            match File::open(path) {
                Ok(file) => {
                    let reader = BufReader::new(file);
                    let mut config_args = Vec::new();
                    for line_res in reader.lines() {
                        if let Ok(line) = line_res {
                            let trimmed = line.trim();
                            if trimmed.is_empty() || trimmed.starts_with('#') {
                                continue;
                            }
                            if let Some(words) = shlex::split(trimmed) {
                                for w in words {
                                    config_args.push(OsString::from(w));
                                }
                            }
                        }
                    }
                    let mut result = Vec::new();
                    if !raw_args.is_empty() {
                        result.push(raw_args[0].clone());
                    }
                    result.extend(config_args);
                    if raw_args.len() > 1 {
                        result.extend(raw_args[1..].iter().cloned());
                    }
                    return result;
                }
                Err(e) => {
                    eprintln!(
                        "rg: failed to read the file specified in RIPGREP_CONFIG_PATH: {}: {}",
                        path.display(),
                        e
                    );
                }
            }
        }
    }

    raw_args
}
EOF"}

