{"command":"cat <<'EOF' > src/generate.rs
use clap::Command;
use clap_complete::Shell;

pub fn print_completion(kind: &str, mut cmd: Command) -> bool {
    let shell = match kind {
        "complete-bash" | "bash" => Some(Shell::Bash),
        "complete-zsh" | "zsh" => Some(Shell::Zsh),
        "complete-fish" | "fish" => Some(Shell::Fish),
        "complete-powershell" | "powershell" => Some(Shell::PowerShell),
        _ => None,
    };

    if let Some(s) = shell {
        clap_complete::generate(s, &mut cmd, "rg", &mut std::io::stdout());
        true
    } else if kind == "man" {
        let man = clap_mangen::Man::new(cmd);
        let mut buffer = Vec::new();
        if man.render(&mut buffer).is_ok() {
            let _ = std::io::Write::write_all(&mut std::io::stdout(), &buffer);
        }
        true
    } else {
        false
    }
}
EOF"}

