{"command":"cat <<'EOF' > src/walker.rs
use ignore::overrides::OverrideBuilder;
use ignore::types::TypesBuilder;
use ignore::{WalkBuilder, WalkParallel};
use std::path::{Path, PathBuf};

pub struct WalkerConfig {
    pub paths: Vec<PathBuf>,
    pub hidden: bool,
    pub no_ignore: bool,
    pub no_ignore_vcs: bool,
    pub no_ignore_parent: bool,
    pub no_ignore_dot: bool,
    pub no_ignore_global: bool,
    pub no_ignore_exclude: bool,
    pub no_ignore_files: bool,
    pub ignore_files: Vec<PathBuf>,
    pub max_depth: Option<usize>,
    pub follow: bool,
    pub one_file_system: bool,
    pub max_filesize: Option<u64>,
    pub threads: usize,
    pub sort: Option<String>,
    pub sort_reverse: bool,
    pub globs: Vec<String>,
    pub iglobs: Vec<String>,
    pub glob_case_insensitive: bool,
    pub types: Vec<String>,
    pub types_not: Vec<String>,
    pub type_adds: Vec<String>,
    pub type_clears: Vec<String>,
}

impl WalkerConfig {
    pub fn build_walker(&self) -> Result<WalkBuilder, String> {
        if self.paths.is_empty() {
            return Err("No paths provided".to_string());
        }

        let first_path = &self.paths[0];
        let mut builder = WalkBuilder::new(first_path);

        for p in self.paths.iter().skip(1) {
            builder.add(p);
        }

        builder.hidden(!self.hidden);

        if self.no_ignore {
            builder.ignore(false);
            builder.git_ignore(false);
            builder.git_global(false);
            builder.git_exclude(false);
            builder.parents(false);
        } else {
            if self.no_ignore_vcs {
                builder.git_ignore(false);
            }
            if self.no_ignore_parent {
                builder.parents(false);
            }
            if self.no_ignore_dot {
                builder.ignore(false);
            }
            if self.no_ignore_global {
                builder.git_global(false);
            }
            if self.no_ignore_exclude {
                builder.git_exclude(false);
            }
        }

        for ig in &self.ignore_files {
            builder.add_ignore(ig);
        }

        if let Some(depth) = self.max_depth {
            builder.max_depth(Some(depth));
        }

        builder.follow_links(self.follow);
        builder.same_file_system(self.one_file_system);

        if let Some(sz) = self.max_filesize {
            builder.max_filesize(Some(sz));
        }

        if self.threads > 0 {
            builder.threads(self.threads);
        }

        // Build types
        let mut types_builder = TypesBuilder::new();
        types_builder.add_defaults();

        for tc in &self.type_clears {
            types_builder.clear(tc);
        }
        for ta in &self.type_adds {
            if let Err(e) = types_builder.add_def(ta) {
                return Err(format!("rg: error adding type definition '{}': {}", ta, e));
            }
        }
        for t in &self.types {
            if t == "all" {
                types_builder.select("all");
            } else {
                types_builder.select(t);
            }
        }
        for tn in &self.types_not {
            types_builder.negate(tn);
        }

        match types_builder.build() {
            Ok(matcher) => {
                builder.types(matcher);
            }
            Err(e) => return Err(format!("rg: error building types matcher: {}", e)),
        }

        // Build overrides/globs
        if !self.globs.is_empty() || !self.iglobs.is_empty() {
            let root = Path::new(".");
            let mut ov_builder = OverrideBuilder::new(root);
            if self.glob_case_insensitive {
                ov_builder.case_insensitive(true).unwrap();
            }
            for g in &self.globs {
                if let Err(e) = ov_builder.add(g) {
                    return Err(format!("rg: error adding glob '{}': {}", g, e));
                }
            }
            for ig in &self.iglobs {
                ov_builder.case_insensitive(true).unwrap();
                if let Err(e) = ov_builder.add(ig) {
                    return Err(format!("rg: error adding iglob '{}': {}", ig, e));
                }
            }
            match ov_builder.build() {
                Ok(ov) => {
                    builder.overrides(ov);
                }
                Err(e) => return Err(format!("rg: error building glob overrides: {}", e)),
            }
        }

        // Sorting
        if let Some(ref sort_by) = self.sort {
            let rev = self.sort_reverse;
            match sort_by.as_str() {
                "path" => {
                    builder.sort_by_file_path(move |a, b| {
                        if rev {
                            b.cmp(a)
                        } else {
                            a.cmp(b)
                        }
                    });
                }
                _ => {
                    builder.sort_by_file_name(move |a, b| {
                        if rev {
                            b.cmp(a)
                        } else {
                            a.cmp(b)
                        }
                    });
                }
            }
        }

        Ok(builder)
    }
}
EOF"}

