            return Err("rg: ripgrep requires at least one pattern to execute a search".to_string());
        }

        let mut processed = Vec::new();
        for pat in patterns {
            let mut p = if opts.fixed_strings {
                regex::escape(pat)
            } else {
                pat.clone()
            };

            if opts.word_regexp {
                p = format!(r"\b(?:{})\b", p);
            }
            if opts.line_regexp {
                p = format!(r"^(?:{})$", p);
            }
            processed.push(format!("(?:{})", p));
        }

        let combined = processed.join("|");

        let mut builder = RegexBuilder::new(&combined);

        // Case sensitivity logic
        let case_insensitive = if opts.ignore_case {
            true
        } else if opts.case_sensitive {
            false
        } else if opts.smart_case {
            !patterns.iter().any(|p| p.chars().any(|c| c.is_uppercase()))
        } else {
            false
        };

        builder.case_insensitive(case_insensitive);
        builder.multi_line(true);
        if opts.multiline {
            builder.dot_matches_new_line(opts.multiline_dotall);
        }
        if opts.crlf {
            builder.crlf(true);
        }

        match builder.build() {
            Ok(re) => Ok(PatternEngine {
                regex: re,
                patterns: patterns.to_vec(),
            }),
            Err(e) => Err(format!("rg: regex parse error: {}", e)),
        }
    }
}

pub struct LineMatch {
    pub line_number: usize,
    pub byte_offset: usize,
    pub line_bytes: Vec<u8>,
    pub matches: Vec<(usize, usize)>, // (start, end) inside line
}

pub struct FileSearchResult {
    pub path: String,
    pub matches: Vec<LineMatch>,
    pub contexts: Vec<ContextLine>,
    pub total_matches_count: usize,
    pub is_binary: bool,
    pub binary_offset: Option<usize>,
    pub bytes_searched: usize,
}

pub struct ContextLine {
    pub line_number: usize,
    pub line_bytes: Vec<u8>,
    pub is_after: bool,
}

pub fn read_input_content(
    path_str: &str,
    pre_cmd: Option<&str>,
) -> io::Result<(Vec<u8>, bool)> {
    if path_str == "-" {
        let mut buffer = Vec::new();
        io::stdin().read_to_end(&mut buffer)?;
        return Ok((buffer, false));
    }

    let path = Path::new(path_str);

    if let Some(cmd) = pre_cmd {
        if !cmd.is_empty() {
            let output = Command::new(cmd).arg(path).output()?;
            return Ok((output.stdout, false));
        }
    }

    let mut file = File::open(path)?;
    let metadata = file.metadata()?;
    let sz = metadata.len() as usize;
    let mut buffer = Vec::with_capacity(sz);
    file.read_to_end(&mut buffer)?;
    Ok((buffer, false))
}

pub fn search_buffer(
    path_str: &str,
    buffer: &[u8],
    engine: &PatternEngine,
    opts: &SearchOptions,
    null_data: bool,
    after_ctx: usize,
    before_context: usize,
) -> FileSearchResult {
    let delim = if null_data { b'\0' } else { b'\n' };

    let mut line_matches = Vec::new();
    let mut contexts = Vec::new();
    let mut total_matches = 0;
    let mut is_binary = false;
    let mut binary_offset = None;

    // Check for binary data
    if !opts.text {
        // Quick NUL check
        let check_len = buffer.len().min(1024);
        if let Some(nul_pos) = buffer[..check_len].find_byte(b'\0') {
            is_binary = true;
            binary_offset = Some(nul_pos);
        }
    }

    let mut line_num = 1;
    let mut current_offset = 0;
    let mut line_start = 0;

    let lines: Vec<&[u8]> = buffer.split_str(&[delim]).collect();
    let total_lines = lines.len();

    // Store line info
    let mut matching_line_indices = Vec::new();

    for (idx, line) in lines.iter().enumerate() {
        let l_num = idx + 1;
        let line_len = line.len();

        let mut ms = Vec::new();
        for m in engine.regex.find_iter(line) {
            ms.push((m.start(), m.end()));
        }

        let is_match = if opts.invert_match {
            ms.is_empty()
        } else {
            !ms.is_empty()
        };

        if is_match {
            if is_binary && !opts.text {
                // If binary file matches, record binary match and break
                return FileSearchResult {
                    path: path_str.to_string(),
                    matches: vec![],
                    contexts: vec![],
                    total_matches_count: 1,
                    is_binary: true,
                    binary_offset,
                    bytes_searched: buffer.len(),
                };
            }

            total_matches += if opts.invert_match { 1 } else { ms.len().max(1) };
            matching_line_indices.push(idx);

            line_matches.push(LineMatch {
                line_number: l_num,
                byte_offset: current_offset,
                line_bytes: line.to_vec(),
                matches: ms,
            });

            if let Some(max_c) = opts.max_count {
                if line_matches.len() >= max_c {
                    break;
                }
            }
        }

        current_offset += line_len + 1;
    }

    // Build context lines if required
    if before_context > 0 || after_ctx > 0 {
        let mut in_match = vec![false; total_lines];
        for &m_idx in &matching_line_indices {
            in_match[m_idx] = true;
        }

        for &m_idx in &matching_line_indices {
            let start = m_idx.saturating_sub(before_context);
            let end = (m_idx + after_ctx + 1).min(total_lines);

            for c_idx in start..end {
                if !in_match[c_idx] {
                    contexts.push(ContextLine {
                        line_number: c_idx + 1,
                        line_bytes: lines[c_idx].to_vec(),
                        is_after: c_idx > m_idx,
                    });
                }
            }
        }
    }

    FileSearchResult {
        path: path_str.to_string(),
        matches: line_matches,
        contexts,
        total_matches_count: total_matches,
        is_binary: false,
        binary_offset: None,
        bytes_searched: buffer.len(),
    }
}
EOF"}

