{"command":"cat <<'EOF' > src/printer.rs
use crate::json::*;
use crate::search::{ContextLine, FileSearchResult, LineMatch};
use std::io::{self, Write};
use std::path::Path;
use std::time::Duration;

pub struct PrinterOptions {
    pub heading: bool,
    pub line_number: bool,
    pub column: bool,
    pub byte_offset: bool,
    pub with_filename: bool,
    pub color: bool,
    pub path_separator: Option<String>,
    pub field_match_separator: String,
    pub field_context_separator: String,
    pub context_separator: String,
    pub show_context_separator: bool,
    pub only_matching: bool,
    pub replace: Option<String>,
    pub passthru: bool,
    pub trim: bool,
    pub max_columns: Option<usize>,
    pub max_columns_preview: bool,
    pub json: bool,
    pub count_lines: bool,
    pub count_matches: bool,
    pub files_with_matches: bool,
    pub files_without_match: bool,
    pub null_delim: bool,
}

pub struct OverallStats {
    pub searches: usize,
    pub searches_with_match: usize,
    pub bytes_searched: usize,
    pub bytes_printed: usize,
    pub matched_lines: usize,
    pub matches: usize,
}

impl OverallStats {
    pub fn new() -> Self {
        OverallStats {
            searches: 0,
            searches_with_match: 0,
            bytes_searched: 0,
            bytes_printed: 0,
            matched_lines: 0,
            matches: 0,
        }
    }
}

pub fn format_path(path_str: &str, sep: Option<&str>) -> String {
    let p = if path_str.starts_with("./") && path_str.len() > 2 {
        &path_str[2..]
    } else {
        path_str
    };

    if let Some(s) = sep {
        p.replace('/', s)
    } else {
        p.to_string()
    }
}

pub fn print_file_result<W: Write>(
    out: &mut W,
    res: &FileSearchResult,
    opts: &PrinterOptions,
    is_first_file: bool,
    stats: &mut OverallStats,
    file_duration: Duration,
) -> io::Result<()> {
    stats.searches += 1;
    stats.bytes_searched += res.bytes_searched;

    if res.total_matches_count > 0 {
        stats.searches_with_match += 1;
        stats.matched_lines += res.matches.len();
        stats.matches += res.total_matches_count;
    }

    let path_formatted = format_path(&res.path, opts.path_separator.as_deref());

    // Mode: --files-with-matches (-l)
    if opts.files_with_matches {
        if res.total_matches_count > 0 {
            let delim = if opts.null_delim { "\0" } else { "\n" };
            let s = format!("{}{}", path_formatted, delim);
            out.write_all(s.as_bytes())?;
            stats.bytes_printed += s.len();
        }
        return Ok(());
    }

    // Mode: --files-without-match
    if opts.files_without_match {
        if res.total_matches_count == 0 {
            let delim = if opts.null_delim { "\0" } else { "\n" };
            let s = format!("{}{}", path_formatted, delim);
            out.write_all(s.as_bytes())?;
            stats.bytes_printed += s.len();
        }
        return Ok(());
    }

    // Mode: -c / --count
    if opts.count_lines {
        let count_val = res.matches.len();
        let line = if opts.with_filename {
            format!("{}{}{}\n", path_formatted, opts.field_match_separator, count_val)
        } else {
            format!("{}\n", count_val)
        };
        out.write_all(line.as_bytes())?;
        stats.bytes_printed += line.len();
        return Ok(());
    }

    // Mode: --count-matches
    if opts.count_matches {
        let count_val = res.total_matches_count;
        let line = if opts.with_filename {
            format!("{}{}{}\n", path_formatted, opts.field_match_separator, count_val)
        } else {
            format!("{}\n", count_val)
        };
        out.write_all(line.as_bytes())?;
        stats.bytes_printed += line.len();
        return Ok(());
    }

    // Mode: --json
    if opts.json {
        let begin_evt = JsonEvent::Begin(JsonBegin {
            path: make_text_or_bytes(path_formatted.as_bytes()),
        });
        let line = serde_json::to_string(&begin_evt).unwrap() + "\n";
        out.write_all(line.as_bytes())?;
