        stats.bytes_printed += header.len();
    }

    let color_match = "\x1b[0m\x1b[1m\x1b[31m";
    let color_line = "\x1b[0m\x1b[32m";
    let color_path = "\x1b[0m\x1b[35m";
    let color_reset = "\x1b[0m";

