        .get_many::<String>("path")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let mut paths = Vec::new();

    if patterns.is_empty() {
        if let Some(pat) = positional_pattern {
            patterns.push(pat.clone());
            paths.extend(positional_paths);
        } else if !matches.get_flag("files") {
            eprintln!("rg: ripgrep requires at least one pattern to execute a search");
            exit(2);
        } else {
            paths.extend(positional_paths);
        }
