            no_ignore_parent: matches.get_flag("no-ignore-parent"),
            no_ignore_dot: matches.get_flag("no-ignore-dot"),
            no_ignore_global: matches.get_flag("no-ignore-global"),
            no_ignore_exclude: matches.get_flag("no-ignore-exclude"),
