            follow: matches.get_flag("follow"),
            one_file_system: matches.get_flag("one-file-system"),
            max_filesize: None,
            threads: 0,
            sort: matches.get_one::<String>("sort").cloned(),
            sort_reverse: matches.get_one::<String>("sortr").is_some(),
            globs: matches
                .get_many::<String>("glob")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            iglobs: matches
                .get_many::<String>("iglob")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            glob_case_insensitive: matches.get_flag("glob-case-insensitive"),
            types: matches
                .get_many::<String>("type")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            types_not: matches
                .get_many::<String>("type-not")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            type_adds: matches
