        iglobs: matches
            .get_many::<String>("iglob")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        glob_case_insensitive: matches.get_flag("glob-case-insensitive"),
        types: matches
            .get_many::<String>("type")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        types_not: matches
            .get_many::<String>("type-not")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        type_adds: matches
            .get_many::<String>("type-add")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
