    pub searches_with_match: usize,
    pub bytes_searched: usize,
    pub bytes_printed: usize,
    pub matched_lines: usize,
    pub matches: usize,
}

impl OverallStats {
    pub fn new() -> Self {
        OverallStats {
            searches: 0,
            searches_with_match: 0,
            bytes_searched: 0,
            bytes_printed: 0,
            matched_lines: 0,
            matches: 0,
        }
    }
}

pub fn format_path(path_str: &str, sep: Option<&str>) -> String {
    let p = if path_str.starts_with("./") && path_str.len() > 2 {
        &path_str[2..]
    } else {
        path_str
    };

    if let Some(s) = sep {
        p.replace('/', s)
    } else {
        p.to_string()
    }
}

enum OutputItem<'a> {
    Match(&'a LineMatch),
    Context(&'a ContextLine),
}

impl<'a> OutputItem<'a> {
    fn line_number(&self) -> usize {
        match self {
            OutputItem::Match(m) => m.line_number,
            OutputItem::Context(c) => c.line_number,
        }
    }
}

pub fn print_file_result<W: Write>(
    out: &mut W,
    res: &FileSearchResult,
    opts: &PrinterOptions,
    is_first_file: bool,
    stats: &mut OverallStats,
    file_duration: Duration,
) -> io::Result<()> {
    stats.searches += 1;
    stats.bytes_searched += res.bytes_searched;

    if res.total_matches_count > 0 {
        stats.searches_with_match += 1;
        stats.matched_lines += res.matches.len();
        stats.matches += res.total_matches_count;
    }

