            let err_str = e.to_string();
            if e.kind() == clap::error::ErrorKind::DisplayHelp {
                let _ = app.print_help();
                println!();
                exit(0);
            }
            if e.kind() == clap::error::ErrorKind::DisplayVersion {
                println!("ripgrep 14.1.1 (rev 41bff5fc54)");
                exit(0);
            }

            let msg = err_str.lines().next().unwrap_or("error parsing flags");
            eprintln!("rg: {}", msg);
            exit(2);
        }
