        println!("ripgrep 14.1.1 (rev 41bff5fc54)\n\nfeatures:-pcre2\nsimd(compile):+SSE2,-SSSE3,-AVX2\nsimd(runtime):+SSE2,+SSSE3,+AVX2\n\nPCRE2 is not available in this build of ripgrep.");
        exit(0);
    }

