use printer::{
    print_file_result, print_summary, OverallStats, PrinterOptions,
};
use search::{
    read_input_content, search_buffer, PatternEngine, SearchOptions,
};
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::{Path, PathBuf};
use std::process::exit;
use std::time::Instant;
use walker::WalkerConfig;

fn main() {
    let start_time = Instant::now();
    let args = config::get_effective_args();

    let mut app = cli::build_cli();
    let matches = match app.try_get_matches_from_mut(args) {
        Ok(m) => m,
        Err(e) => {
            let err_str = e.to_string();
            if e.kind() == clap::error::ErrorKind::DisplayHelp {
                let _ = app.print_help();
                println!();
                exit(0);
            }
            if e.kind() == clap::error::ErrorKind::DisplayVersion {
                println!("ripgrep 14.1.1 (rev 41bff5fc54)");
                exit(0);
            }

            let msg = err_str.lines().next().unwrap_or("error parsing flags");
            eprintln!("rg: {}", msg);
            exit(2);
        }
    };

    // Check version flags
    if matches.get_flag("version_short") {
        println!("ripgrep 14.1.1 (rev 41bff5fc54)");
        exit(0);
    }
    if matches.get_flag("version_long") {
        println!("ripgrep 14.1.1 (rev 41bff5fc54)\n\nfeatures:-pcre2\nsimd(compile):+SSE2,-SSSE3,-AVX2\nsimd(runtime):+SSE2,+SSSE3,+AVX2\n\nPCRE2 is not available in this build of ripgrep.");
        exit(0);
    }

    // Check help flags
    if matches.get_flag("help_short") {
        let _ = app.print_help();
        println!();
        exit(0);
    }
    if matches.get_flag("help_long") {
        let _ = app.print_long_help();
        println!();
        exit(0);
    }

    // Check PCRE2
    if matches.get_flag("pcre2-version") {
        println!("PCRE2 is not available in this build of ripgrep.");
        exit(1);
    }
    if matches.get_flag("pcre2") {
        eprintln!("rg: PCRE2 is not available in this build of ripgrep");
        exit(2);
    }

    // Check --generate
    if let Some(kind) = matches.get_one::<String>("generate") {
        if generate::print_completion(kind, app) {
            exit(0);
        } else {
            eprintln!("rg: unknown generate kind '{}'", kind);
            exit(2);
        }
    }

    // Check --type-list
    if matches.get_flag("type-list") {
        let mut builder = TypesBuilder::new();
        builder.add_defaults();

        if let Some(clears) = matches.get_many::<String>("type-clear") {
            for c in clears {
                builder.clear(c);
            }
        }
        if let Some(adds) = matches.get_many::<String>("type-add") {
            for a in adds {
                let _ = builder.add_def(a);
            }
        }

        if let Ok(types) = builder.build() {
            for def in types.definitions() {
                let globs: Vec<&str> = def.globs().iter().map(|s| s.as_str()).collect();
                println!("{}: {}", def.name(), globs.join(", "));
            }
        }
        exit(0);
    }

    let mut patterns = Vec::new();

    if let Some(regexps) = matches.get_many::<String>("regexp") {
        for r in regexps {
            patterns.push(r.clone());
        }
    }

    if let Some(files) = matches.get_many::<String>("file") {
        for f in files {
            if f == "-" {
                let stdin = io::stdin();
                for line in stdin.lock().lines().flatten() {
                    patterns.push(line);
                }
            } else if let Ok(file) = File::open(f) {
                let reader = BufReader::new(file);
                for line in reader.lines().flatten() {
                    patterns.push(line);
                }
            } else {
                eprintln!("rg: failed to open pattern file {}: No such file or directory (os error 2)", f);
                exit(2);
            }
        }
    }

    let positional_pattern = matches.get_one::<String>("pattern_pos");
    let positional_paths: Vec<String> = matches
        .get_many::<String>("path")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let mut paths = Vec::new();

    if matches.get_flag("files") {
        if let Some(pat) = positional_pattern {
            paths.push(pat.clone());
        }
        paths.extend(positional_paths);
    } else if patterns.is_empty() {
        if let Some(pat) = positional_pattern {
            patterns.push(pat.clone());
            paths.extend(positional_paths);
        } else {
            eprintln!("rg: ripgrep requires at least one pattern to execute a search");
            exit(2);
        }
    } else {
        if let Some(pat) = positional_pattern {
            paths.push(pat.clone());
        }
        paths.extend(positional_paths);
    }

    let stdin_is_tty = io::stdin().is_terminal();
    let stdout_is_tty = io::stdout().is_terminal();

    if paths.is_empty() {
        if stdin_is_tty {
            paths.push(".".to_string());
        } else {
            paths.push("-".to_string());
        }
    }

    // Check mode: --files
    if matches.get_flag("files") {
        let walker_cfg = WalkerConfig {
            paths: paths.iter().map(PathBuf::from).collect(),
            hidden: matches.get_flag("hidden"),
            no_ignore: matches.get_flag("no-ignore"),
            no_ignore_vcs: matches.get_flag("no-ignore-vcs"),
            no_ignore_parent: matches.get_flag("no-ignore-parent"),
            no_ignore_dot: matches.get_flag("no-ignore-dot"),
            no_ignore_global: matches.get_flag("no-ignore-global"),
            no_ignore_exclude: matches.get_flag("no-ignore-exclude"),
            no_ignore_files: matches.get_flag("no-ignore-files"),
            ignore_files: matches
                .get_many::<String>("ignore-file")
                .map(|v| v.map(PathBuf::from).collect())
                .unwrap_or_default(),
            max_depth: matches
                .get_one::<String>("max-depth")
                .and_then(|s| s.parse().ok()),
            follow: matches.get_flag("follow"),
            one_file_system: matches.get_flag("one-file-system"),
            max_filesize: None,
            threads: 0,
            sort: matches.get_one::<String>("sort").cloned(),
            sort_reverse: matches.get_one::<String>("sortr").is_some(),
            globs: matches
                .get_many::<String>("glob")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            iglobs: matches
                .get_many::<String>("iglob")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            glob_case_insensitive: matches.get_flag("glob-case-insensitive"),
            types: matches
                .get_many::<String>("type")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            types_not: matches
                .get_many::<String>("type-not")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            type_adds: matches
                .get_many::<String>("type-add")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            type_clears: matches
                .get_many::<String>("type-clear")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
        };

        if let Ok(builder) = walker_cfg.build_walker() {
            let delim = if matches.get_flag("null") { "\0" } else { "\n" };
            for entry in builder.build().flatten() {
                if entry.file_type().map_or(false, |ft| ft.is_file()) {
                    let path_str = entry.path().display().to_string();
                    let formatted = printer::format_path(&path_str, matches.get_one::<String>("path-separator").map(|s| s.as_str()));
                    print!("{}{}", formatted, delim);
                }
            }
        }
        exit(0);
    }

    let search_opts = SearchOptions {
        case_sensitive: matches.get_flag("case-sensitive"),
        smart_case: matches.get_flag("smart-case"),
        ignore_case: matches.get_flag("ignore-case"),
        fixed_strings: matches.get_flag("fixed-strings"),
        word_regexp: matches.get_flag("word-regexp"),
        line_regexp: matches.get_flag("line-regexp"),
        invert_match: matches.get_flag("invert-match"),
        multiline: matches.get_flag("multiline"),
        multiline_dotall: matches.get_flag("multiline-dotall"),
        crlf: matches.get_flag("crlf"),
        text: matches.get_flag("text"),
        binary: matches.get_flag("binary"),
        max_count: matches
            .get_one::<String>("max-count")
            .and_then(|s| s.parse().ok()),
        pre: matches.get_one::<String>("pre").cloned(),
        pre_globs: matches
            .get_many::<String>("pre-glob")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
    };

    let engine = match PatternEngine::new(&patterns, &search_opts) {
        Ok(e) => e,
        Err(err) => {
            eprintln!("{}", err);
            exit(2);
        }
    };

    let is_multiple_paths = paths.len() > 1 || (paths.len() == 1 && Path::new(&paths[0]).is_dir());

    let heading = if matches.get_flag("no-heading") {
        false
    } else if matches.get_flag("heading") || matches.get_flag("pretty") {
        true
    } else {
        stdout_is_tty && !matches.get_flag("vimgrep")
    };

    let line_number = if matches.get_flag("no-line-number") {
        false
    } else if matches.get_flag("line-number") || matches.get_flag("pretty") || matches.get_flag("vimgrep") {
        true
    } else {
        stdout_is_tty
    };

    let with_filename = if matches.get_flag("no-filename") {
        false
    } else if matches.get_flag("with-filename") || matches.get_flag("vimgrep") {
        true
    } else {
        is_multiple_paths && !matches.get_flag("heading")
    };

    let color = match matches.get_one::<String>("color").map(|s| s.as_str()) {
        Some("always") | Some("ansi") => true,
        Some("never") => false,
        _ => stdout_is_tty || matches.get_flag("pretty"),
    };

    let context_val: usize = matches
        .get_one::<String>("context")
        .and_then(|s| s.parse().ok())
        .unwrap_or(0);
    let after_ctx: usize = matches
        .get_one::<String>("after-context")
        .and_then(|s| s.parse().ok())
        .unwrap_or(context_val);
    let before_ctx: usize = matches
        .get_one::<String>("before-context")
        .and_then(|s| s.parse().ok())
        .unwrap_or(context_val);

    let printer_opts = PrinterOptions {
        heading,
        line_number,
        column: matches.get_flag("column") || matches.get_flag("vimgrep"),
        byte_offset: matches.get_flag("byte-offset"),
        with_filename,
        color,
        path_separator: matches.get_one::<String>("path-separator").cloned(),
        field_match_separator: matches
            .get_one::<String>("field-match-separator")
            .cloned()
            .unwrap_or_else(|| ":".to_string()),
        field_context_separator: matches
            .get_one::<String>("field-context-separator")
            .cloned()
            .unwrap_or_else(|| "-".to_string()),
        context_separator: matches
            .get_one::<String>("context-separator")
            .cloned()
            .unwrap_or_else(|| "--".to_string()),
        show_context_separator: !matches.get_flag("no-context-separator"),
        only_matching: matches.get_flag("only-matching"),
        replace: matches.get_one::<String>("replace").cloned(),
        passthru: matches.get_flag("passthru"),
        trim: matches.get_flag("trim"),
        max_columns: matches
            .get_one::<String>("max-columns")
            .and_then(|s| s.parse().ok()),
        max_columns_preview: matches.get_flag("max-columns-preview"),
        json: matches.get_flag("json"),
        count_lines: matches.get_flag("count"),
        count_matches: matches.get_flag("count-matches"),
        files_with_matches: matches.get_flag("files-with-matches"),
        files_without_match: matches.get_flag("files-without-match"),
        null_delim: matches.get_flag("null"),
    };

    let walker_cfg = WalkerConfig {
        paths: paths.iter().map(PathBuf::from).collect(),
        hidden: matches.get_flag("hidden"),
        no_ignore: matches.get_flag("no-ignore"),
        no_ignore_vcs: matches.get_flag("no-ignore-vcs"),
        no_ignore_parent: matches.get_flag("no-ignore-parent"),
        no_ignore_dot: matches.get_flag("no-ignore-dot"),
        no_ignore_global: matches.get_flag("no-ignore-global"),
        no_ignore_exclude: matches.get_flag("no-ignore-exclude"),
        no_ignore_files: matches.get_flag("no-ignore-files"),
        ignore_files: matches
            .get_many::<String>("ignore-file")
            .map(|v| v.map(PathBuf::from).collect())
            .unwrap_or_default(),
        max_depth: matches
            .get_one::<String>("max-depth")
            .and_then(|s| s.parse().ok()),
        follow: matches.get_flag("follow"),
        one_file_system: matches.get_flag("one-file-system"),
        max_filesize: None,
        threads: 0,
        sort: matches.get_one::<String>("sort").cloned(),
        sort_reverse: matches.get_one::<String>("sortr").is_some(),
        globs: matches
            .get_many::<String>("glob")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        iglobs: matches
            .get_many::<String>("iglob")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        glob_case_insensitive: matches.get_flag("glob-case-insensitive"),
        types: matches
            .get_many::<String>("type")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        types_not: matches
            .get_many::<String>("type-not")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        type_adds: matches
            .get_many::<String>("type-add")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        type_clears: matches
            .get_many::<String>("type-clear")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
    };

    let mut overall_stats = OverallStats::new();
    let mut out = io::stdout();
    let mut is_first_file = true;

    if paths.len() == 1 && paths[0] == "-" {
        if let Ok((buffer, _)) = read_input_content("-", None) {
            let f_start = Instant::now();
            let res = search_buffer(
                "<stdin>",
                &buffer,
                &engine,
                &search_opts,
                matches.get_flag("null-data"),
                after_ctx,
                before_ctx,
            );
            let f_dur = f_start.elapsed();
            let _ = print_file_result(&mut out, &res, &printer_opts, is_first_file, &mut overall_stats, f_dur);
        }
    } else if let Ok(builder) = walker_cfg.build_walker() {
        let is_single_explicit_file = paths.len() == 1 && Path::new(&paths[0]).is_file();

        for entry in builder.build() {
            match entry {
                Ok(e) => {
                    if e.file_type().map_or(false, |ft| ft.is_file()) {
                        let path_str = e.path().display().to_string();
                        if let Ok((buffer, _)) = read_input_content(&path_str, search_opts.pre.as_deref()) {
                            let f_start = Instant::now();
                            let res = search_buffer(
                                &path_str,
                                &buffer,
                                &engine,
                                &search_opts,
                                matches.get_flag("null-data"),
                                after_ctx,
                                before_ctx,
                            );
                            let f_dur = f_start.elapsed();

                            // Binary check: if not explicit file and is binary and not --text and not --binary, skip
                            if res.is_binary && !is_single_explicit_file && !search_opts.text && !search_opts.binary {
                                continue;
                            }

                            let _ = print_file_result(
                                &mut out,
                                &res,
                                &printer_opts,
                                is_first_file,
                                &mut overall_stats,
                                f_dur,
                            );
                            if res.total_matches_count > 0 {
                                is_first_file = false;
                            }
                        }
                    }
                }
                Err(e) => {
                    if !matches.get_flag("no-messages") {
                        eprintln!("rg: {}", e);
                    }
                }
            }
        }
    }

    let total_duration = start_time.elapsed();

    if matches.get_flag("stats") || printer_opts.json {
        let _ = print_summary(&mut out, &printer_opts, &overall_stats, total_duration);
    }

    if overall_stats.matches > 0 || (matches.get_flag("files-without-match") && overall_stats.searches > overall_stats.searches_with_match) {
        exit(0);
    } else {
        exit(1);
    }
}
EOF"}

