use bstr::ByteSlice;
use regex::bytes::{Regex, RegexBuilder};
use std::fs::File;
use std::io::{self, Read};
use std::path::Path;
use std::process::Command;

pub struct SearchOptions {
    pub case_sensitive: bool,
    pub smart_case: bool,
    pub ignore_case: bool,
    pub fixed_strings: bool,
    pub word_regexp: bool,
    pub line_regexp: bool,
    pub invert_match: bool,
    pub multiline: bool,
    pub multiline_dotall: bool,
    pub crlf: bool,
    pub text: bool,
    pub binary: bool,
    pub max_count: Option<usize>,
    pub pre: Option<String>,
    pub pre_globs: Vec<String>,
}

pub struct PatternEngine {
    pub regex: Regex,
    pub patterns: Vec<String>,
}

impl PatternEngine {
    pub fn new(patterns: &[String], opts: &SearchOptions) -> Result<Self, String> {
        if patterns.is_empty() {
            return Err("rg: ripgrep requires at least one pattern to execute a search".to_string());
        }

        let mut processed = Vec::new();
        for pat in patterns {
            let mut p = if opts.fixed_strings {
                regex::escape(pat)
            } else {
                pat.clone()
            };

            if opts.word_regexp {
                p = format!(r"\b(?:{})\b", p);
            }
            if opts.line_regexp {
                p = format!(r"^(?:{})$", p);
            }
            processed.push(format!("(?:{})", p));
        }

        let combined = processed.join("|");

        let mut builder = RegexBuilder::new(&combined);

        let case_insensitive = if opts.ignore_case {
            true
        } else if opts.case_sensitive {
            false
        } else if opts.smart_case {
            !patterns.iter().any(|p| p.chars().any(|c| c.is_uppercase()))
        } else {
            false
        };

        builder.case_insensitive(case_insensitive);
        builder.multi_line(true);
        if opts.multiline {
            builder.dot_matches_new_line(opts.multiline_dotall);
        }
        if opts.crlf {
            builder.crlf(true);
        }

        match builder.build() {
            Ok(re) => Ok(PatternEngine {
                regex: re,
                patterns: patterns.to_vec(),
            }),
            Err(e) => Err(format!("rg: regex parse error: {}", e)),
        }
    }
}

pub struct LineMatch {
    pub line_number: usize,
    pub byte_offset: usize,
    pub line_bytes: Vec<u8>,
    pub matches: Vec<(usize, usize)>,
}

pub struct FileSearchResult {
    pub path: String,
    pub matches: Vec<LineMatch>,
    pub contexts: Vec<ContextLine>,
    pub total_matches_count: usize,
    pub is_binary: bool,
    pub binary_offset: Option<usize>,
    pub bytes_searched: usize,
}

pub struct ContextLine {
    pub line_number: usize,
    pub line_bytes: Vec<u8>,
    pub is_after: bool,
}

pub fn read_input_content(
    path_str: &str,
    pre_cmd: Option<&str>,
) -> io::Result<(Vec<u8>, bool)> {
    if path_str == "-" {
        let mut buffer = Vec::new();
        io::stdin().read_to_end(&mut buffer)?;
        return Ok((buffer, false));
    }

    let path = Path::new(path_str);

    if let Some(cmd) = pre_cmd {
        if !cmd.is_empty() {
            let output = Command::new(cmd).arg(path).output()?;
            return Ok((output.stdout, false));
        }
    }

    let mut file = File::open(path)?;
    let metadata = file.metadata()?;
    let sz = metadata.len() as usize;
    let mut buffer = Vec::with_capacity(sz);
    file.read_to_end(&mut buffer)?;
    Ok((buffer, false))
}

pub fn search_buffer(
    path_str: &str,
    buffer: &[u8],
    engine: &PatternEngine,
    opts: &SearchOptions,
    null_data: bool,
    after_ctx: usize,
    before_context: usize,
) -> FileSearchResult {
    let delim = if null_data { b'\0' } else { b'\n' };

    let mut line_matches = Vec::new();
    let mut contexts = Vec::new();
    let mut total_matches = 0;
    let mut is_binary = false;
    let mut binary_offset = None;

    if !opts.text {
        let check_len = buffer.len().min(1024);
        if let Some(nul_pos) = buffer[..check_len].find_byte(b'\0') {
            is_binary = true;
            binary_offset = Some(nul_pos);
        }
    }

