use serde::Serialize;
use std::time::Duration;

#[derive(Serialize)]
#[serde(untagged)]
pub enum JsonTextOrBytes<'a> {
    Text { text: &'a str },
    Bytes { bytes: String },
}

pub fn make_text_or_bytes(bytes: &[u8]) -> JsonTextOrBytes<'_> {
    match std::str::from_utf8(bytes) {
        Ok(s) => JsonTextOrBytes::Text { text: s },
        Err(_) => {
            use base64::Engine;
            let encoded = base64::engine::general_purpose::STANDARD.encode(bytes);
            JsonTextOrBytes::Bytes { bytes: encoded }
        }
    }
}

#[derive(Serialize)]
pub struct JsonBegin<'a> {
    pub path: JsonTextOrBytes<'a>,
}

#[derive(Serialize)]
pub struct JsonSubmatchData<'a> {
    #[serde(rename = "match")]
    pub match_text: JsonTextOrBytes<'a>,
    pub start: usize,
    pub end: usize,
}

#[derive(Serialize)]
pub struct JsonMatchData<'a> {
    pub path: JsonTextOrBytes<'a>,
    pub lines: JsonTextOrBytes<'a>,
    pub line_number: Option<usize>,
    pub absolute_offset: usize,
    pub submatches: Vec<JsonSubmatchData<'a>>,
}

#[allow(dead_code)]
#[derive(Serialize)]
pub struct JsonContextData<'a> {
    pub path: JsonTextOrBytes<'a>,
    pub lines: JsonTextOrBytes<'a>,
    pub line_number: Option<usize>,
    pub absolute_offset: usize,
    pub submatches: Vec<JsonSubmatchData<'a>>,
}

#[derive(Serialize)]
pub struct JsonElapsed {
    pub secs: u64,
    pub nanos: u32,
    pub human: String,
}

impl JsonElapsed {
    pub fn new(dur: Duration) -> Self {
        let secs = dur.as_secs();
        let nanos = dur.subsec_nanos();
        let human = format!("{:.6}s", dur.as_secs_f64());
        JsonElapsed { secs, nanos, human }
    }
}

#[derive(Serialize)]
pub struct JsonStats {
    pub elapsed: JsonElapsed,
    pub searches: usize,
    pub searches_with_match: usize,
    pub bytes_searched: usize,
    pub bytes_printed: usize,
    pub matched_lines: usize,
    pub matches: usize,
}

#[derive(Serialize)]
pub struct JsonEndData<'a> {
    pub path: JsonTextOrBytes<'a>,
    pub binary_offset: Option<usize>,
    pub stats: JsonStats,
}

#[derive(Serialize)]
pub struct JsonSummaryData {
    pub elapsed_total: JsonElapsed,
    pub stats: JsonStats,
}

#[allow(dead_code)]
#[derive(Serialize)]
#[serde(tag = "type", content = "data")]
#[serde(rename_all = "snake_case")]
pub enum JsonEvent<'a> {
    Begin(JsonBegin<'a>),
    Match(JsonMatchData<'a>),
    Context(JsonContextData<'a>),
    End(JsonEndData<'a>),
    Summary(JsonSummaryData),
}
EOF"}

