use crate::json::*;
use crate::search::{ContextLine, FileSearchResult, LineMatch};
use std::io::{self, Write};
use std::time::Duration;

#[allow(dead_code)]
pub struct PrinterOptions {
    pub heading: bool,
    pub line_number: bool,
    pub column: bool,
    pub byte_offset: bool,
    pub with_filename: bool,
    pub color: bool,
    pub path_separator: Option<String>,
    pub field_match_separator: String,
    pub field_context_separator: String,
    pub context_separator: String,
    pub show_context_separator: bool,
    pub only_matching: bool,
    pub replace: Option<String>,
    pub passthru: bool,
    pub trim: bool,
    pub max_columns: Option<usize>,
    pub max_columns_preview: bool,
    pub json: bool,
    pub count_lines: bool,
    pub count_matches: bool,
    pub files_with_matches: bool,
    pub files_without_match: bool,
    pub null_delim: bool,
}

pub struct OverallStats {
    pub searches: usize,
    pub searches_with_match: usize,
    pub bytes_searched: usize,
    pub bytes_printed: usize,
    pub matched_lines: usize,
    pub matches: usize,
}

impl OverallStats {
    pub fn new() -> Self {
        OverallStats {
            searches: 0,
            searches_with_match: 0,
            bytes_searched: 0,
            bytes_printed: 0,
            matched_lines: 0,
            matches: 0,
        }
    }
}

pub fn format_path(path_str: &str, sep: Option<&str>) -> String {
    let p = if path_str.starts_with("./") && path_str.len() > 2 {
        &path_str[2..]
    } else {
        path_str
    };

    if let Some(s) = sep {
        p.replace('/', s)
    } else {
        p.to_string()
    }
}

enum OutputItem<'a> {
    Match(&'a LineMatch),
    Context(&'a ContextLine),
}

impl<'a> OutputItem<'a> {
    fn line_number(&self) -> usize {
        match self {
            OutputItem::Match(m) => m.line_number,
            OutputItem::Context(c) => c.line_number,
        }
    }
}

pub fn print_file_result<W: Write>(
    out: &mut W,
    res: &FileSearchResult,
    opts: &PrinterOptions,
    is_first_file: bool,
    stats: &mut OverallStats,
    file_duration: Duration,
) -> io::Result<()> {
    stats.searches += 1;
    stats.bytes_searched += res.bytes_searched;

    if res.total_matches_count > 0 {
        stats.searches_with_match += 1;
        stats.matched_lines += res.matches.len();
        stats.matches += res.total_matches_count;
    }

    let path_formatted = format_path(&res.path, opts.path_separator.as_deref());

    if opts.files_with_matches {
        if res.total_matches_count > 0 {
            let delim = if opts.null_delim { "\0" } else { "\n" };
            let s = format!("{}{}", path_formatted, delim);
            out.write_all(s.as_bytes())?;
            stats.bytes_printed += s.len();
        }
        return Ok(());
    }

    if opts.files_without_match {
        if res.total_matches_count == 0 {
            let delim = if opts.null_delim { "\0" } else { "\n" };
            let s = format!("{}{}", path_formatted, delim);
            out.write_all(s.as_bytes())?;
            stats.bytes_printed += s.len();
        }
        return Ok(());
    }

    if opts.count_lines {
        let count_val = res.matches.len();
        let line = if opts.with_filename {
            format!("{}{}{}\n", path_formatted, opts.field_match_separator, count_val)
        } else {
            format!("{}\n", count_val)
        };
        out.write_all(line.as_bytes())?;
        stats.bytes_printed += line.len();
        return Ok(());
    }

    if opts.count_matches {
        let count_val = res.total_matches_count;
        let line = if opts.with_filename {
            format!("{}{}{}\n", path_formatted, opts.field_match_separator, count_val)
        } else {
            format!("{}\n", count_val)
        };
        out.write_all(line.as_bytes())?;
        stats.bytes_printed += line.len();
        return Ok(());
    }

    if opts.json {
        let begin_evt = JsonEvent::Begin(JsonBegin {
            path: make_text_or_bytes(path_formatted.as_bytes()),
        });
        let line = serde_json::to_string(&begin_evt).unwrap() + "\n";
        out.write_all(line.as_bytes())?;
        stats.bytes_printed += line.len();

        for m in &res.matches {
            let mut line_bytes = m.line_bytes.clone();
            if !line_bytes.ends_with(b"\n") {
                line_bytes.push(b'\n');
            }

            let submatches: Vec<JsonSubmatchData> = m
                .matches
                .iter()
                .map(|&(s, e)| {
                    let sub_slice = &m.line_bytes[s..e];
                    JsonSubmatchData {
                        match_text: make_text_or_bytes(sub_slice),
                        start: s,
                        end: e,
                    }
                })
                .collect();

            let match_evt = JsonEvent::Match(JsonMatchData {
                path: make_text_or_bytes(path_formatted.as_bytes()),
                lines: make_text_or_bytes(&line_bytes),
                line_number: if opts.line_number { Some(m.line_number) } else { None },
                absolute_offset: m.byte_offset,
                submatches,
            });
            let line = serde_json::to_string(&match_evt).unwrap() + "\n";
            out.write_all(line.as_bytes())?;
            stats.bytes_printed += line.len();
        }

        let file_stats = JsonStats {
            elapsed: JsonElapsed::new(file_duration),
            searches: 1,
            searches_with_match: if res.total_matches_count > 0 { 1 } else { 0 },
            bytes_searched: res.bytes_searched,
            bytes_printed: stats.bytes_printed,
            matched_lines: res.matches.len(),
            matches: res.total_matches_count,
        };

        let end_evt = JsonEvent::End(JsonEndData {
            path: make_text_or_bytes(path_formatted.as_bytes()),
            binary_offset: res.binary_offset,
            stats: file_stats,
        });
        let line = serde_json::to_string(&end_evt).unwrap() + "\n";
        out.write_all(line.as_bytes())?;
        stats.bytes_printed += line.len();

        return Ok(());
    }

    if res.is_binary {
        if res.total_matches_count > 0 {
            let offset_str = if let Some(off) = res.binary_offset {
                format!(" (found \"\\0\" byte around offset {})", off)
            } else {
                "".to_string()
            };
            let line = if opts.with_filename {
                format!("{}: binary file matches{}\n", path_formatted, offset_str)
            } else {
                format!("binary file matches{}\n", offset_str)
            };
            out.write_all(line.as_bytes())?;
            stats.bytes_printed += line.len();
        }
        return Ok(());
    }

    if res.matches.is_empty() {
        return Ok(());
    }

    if opts.heading {
        if !is_first_file {
            out.write_all(b"\n")?;
            stats.bytes_printed += 1;
        }
        let header = if opts.color {
            format!("\x1b[0m\x1b[35m{}\x1b[0m\n", path_formatted)
        } else {
            format!("{}\n", path_formatted)
        };
        out.write_all(header.as_bytes())?;
        stats.bytes_printed += header.len();
    }

    let color_match = "\x1b[0m\x1b[1m\x1b[31m";
    let color_line = "\x1b[0m\x1b[32m";
    let color_path = "\x1b[0m\x1b[35m";
    let color_reset = "\x1b[0m";

    let mut items: Vec<OutputItem> = Vec::new();
    for m in &res.matches {
        items.push(OutputItem::Match(m));
    }
    for c in &res.contexts {
        items.push(OutputItem::Context(c));
    }
    items.sort_by_key(|i| i.line_number());

    let mut last_line: usize = 0;

    for item in items {
        let cur_line = item.line_number();

        if last_line > 0 && cur_line > last_line + 1 && opts.show_context_separator {
            let sep_line = format!("{}\n", opts.context_separator);
            out.write_all(sep_line.as_bytes())?;
            stats.bytes_printed += sep_line.len();
        }

        last_line = cur_line;

        match item {
            OutputItem::Match(m) => {
                let mut line_str = String::from_utf8_lossy(&m.line_bytes).to_string();

                if opts.trim {
                    line_str = line_str.trim_start().to_string();
                }

                if let Some(max_col) = opts.max_columns {
                    if line_str.len() > max_col {
                        if opts.max_columns_preview {
