        }

        let file_stats = JsonStats {
            elapsed: JsonElapsed::new(file_duration),
            searches: 1,
            searches_with_match: if res.total_matches_count > 0 { 1 } else { 0 },
            bytes_searched: res.bytes_searched,
            bytes_printed: stats.bytes_printed,
            matched_lines: res.matches.len(),
            matches: res.total_matches_count,
        };

        let end_evt = JsonEvent::End(JsonEndData {
            path: make_text_or_bytes(path_formatted.as_bytes()),
            binary_offset: res.binary_offset,
            stats: file_stats,
        });
        let line = serde_json::to_string(&end_evt).unwrap() + "\n";
        out.write_all(line.as_bytes())?;
        stats.bytes_printed += line.len();

        return Ok(());
    }

    if res.is_binary {
        if res.total_matches_count > 0 {
            let offset_str = if let Some(off) = res.binary_offset {
                format!(" (found \"\\0\" byte around offset {})", off)
            } else {
                "".to_string()
            };
            let line = if opts.with_filename {
                format!("{}: binary file matches{}\n", path_formatted, offset_str)
            } else {
                format!("binary file matches{}\n", offset_str)
            };
            out.write_all(line.as_bytes())?;
            stats.bytes_printed += line.len();
        }
        return Ok(());
    }

    if res.matches.is_empty() {
        return Ok(());
    }

    if opts.heading {
        if !is_first_file {
            out.write_all(b"\n")?;
            stats.bytes_printed += 1;
        }
        let header = if opts.color {
            format!("\x1b[0m\x1b[35m{}\x1b[0m\n", path_formatted)
        } else {
            format!("{}\n", path_formatted)
        };
        out.write_all(header.as_bytes())?;
        stats.bytes_printed += header.len();
    }

    let color_match = "\x1b[0m\x1b[1m\x1b[31m";
    let color_line = "\x1b[0m\x1b[32m";
    let color_path = "\x1b[0m\x1b[35m";
    let color_reset = "\x1b[0m";

    let mut items: Vec<OutputItem> = Vec::new();
    for m in &res.matches {
        items.push(OutputItem::Match(m));
    }
    for c in &res.contexts {
        items.push(OutputItem::Context(c));
    }
    items.sort_by_key(|i| i.line_number());

    let mut last_line: usize = 0;

    for item in items {
        let cur_line = item.line_number();

        if last_line > 0 && cur_line > last_line + 1 && opts.show_context_separator {
            let sep_line = format!("{}\n", opts.context_separator);
            out.write_all(sep_line.as_bytes())?;
            stats.bytes_printed += sep_line.len();
        }

        last_line = cur_line;

        match item {
            OutputItem::Match(m) => {
                let mut line_str = String::from_utf8_lossy(&m.line_bytes).to_string();

                if opts.trim {
                    line_str = line_str.trim_start().to_string();
                }

                if let Some(max_col) = opts.max_columns {
                    if line_str.len() > max_col {
                        if opts.max_columns_preview {
                            line_str = format!("{} [... omitted end of long line]", &line_str[..max_col]);
                        } else {
                            line_str = "[Omitted long matching line]".to_string();
                        }
                    }
                }

                if let Some(ref repl) = opts.replace {
                    if !m.matches.is_empty() {
                        let mut replaced = String::new();
                        let mut last = 0;
                        for &(start, end) in &m.matches {
                            if start >= last && end <= line_str.len() {
                                replaced.push_str(&line_str[last..start]);
                                replaced.push_str(repl);
                                last = end;
                            }
                        }
                        if last < line_str.len() {
                            replaced.push_str(&line_str[last..]);
                        }
                        line_str = replaced;
                    }
                }

                if opts.color && opts.replace.is_none() && !m.matches.is_empty() {
                    let mut colored_line = String::new();
                    let mut last = 0;
                    for &(start, end) in &m.matches {
                        if start >= last && end <= line_str.len() {
                            colored_line.push_str(&line_str[last..start]);
                            colored_line.push_str(color_match);
                            colored_line.push_str(&line_str[start..end]);
                            colored_line.push_str(color_reset);
                            last = end;
                        }
                    }
                    if last < line_str.len() {
                        colored_line.push_str(&line_str[last..]);
                    }
                    line_str = colored_line;
                }

                if opts.only_matching {
                    for &(start, end) in &m.matches {
                        let sub_str = if start < end && end <= m.line_bytes.len() {
                            String::from_utf8_lossy(&m.line_bytes[start..end]).to_string()
                        } else {
                            "".to_string()
                        };

                        let mut prefix = String::new();
                        if opts.with_filename && !opts.heading {
                            if opts.color {
                                prefix.push_str(&format!("{}{}{}", color_path, path_formatted, color_reset));
                            } else {
                                prefix.push_str(&path_formatted);
                            }
                            prefix.push_str(&opts.field_match_separator);
                        }
                        if opts.line_number {
                            if opts.color {
                                prefix.push_str(&format!("{}{}{}", color_line, m.line_number, color_reset));
                            } else {
                                prefix.push_str(&m.line_number.to_string());
                            }
                            prefix.push_str(&opts.field_match_separator);
                        }
                        if opts.column {
                            let col_num = start + 1;
                            prefix.push_str(&col_num.to_string());
                            prefix.push_str(&opts.field_match_separator);
                        }
                        if opts.byte_offset {
                            let b_off = m.byte_offset + start;
                            prefix.push_str(&b_off.to_string());
                            prefix.push_str(&opts.field_match_separator);
                        }

                        let sub_out = if opts.color {
                            format!("{}{}{}\n", color_match, sub_str, color_reset)
                        } else {
                            format!("{}\n", sub_str)
                        };

                        let line_out = format!("{}{}", prefix, sub_out);
                        out.write_all(line_out.as_bytes())?;
                        stats.bytes_printed += line_out.len();
                    }
                    continue;
                }

                let mut prefix = String::new();
                if opts.with_filename && !opts.heading {
                    if opts.color {
                        prefix.push_str(&format!("{}{}{}", color_path, path_formatted, color_reset));
                    } else {
                        prefix.push_str(&path_formatted);
                    }
                    prefix.push_str(&opts.field_match_separator);
                }
                if opts.line_number {
                    if opts.color {
                        prefix.push_str(&format!("{}{}{}", color_line, m.line_number, color_reset));
                    } else {
                        prefix.push_str(&m.line_number.to_string());
                    }
                    prefix.push_str(&opts.field_match_separator);
                }
                if opts.column {
                    let col_num = m.matches.first().map(|&(s, _)| s + 1).unwrap_or(1);
                    prefix.push_str(&col_num.to_string());
                    prefix.push_str(&opts.field_match_separator);
                }
                if opts.byte_offset {
                    prefix.push_str(&m.byte_offset.to_string());
                    prefix.push_str(&opts.field_match_separator);
                }

                let line_out = format!("{}{}\n", prefix, line_str);
                out.write_all(line_out.as_bytes())?;
                stats.bytes_printed += line_out.len();
            }
            OutputItem::Context(c) => {
                let mut line_str = String::from_utf8_lossy(&c.line_bytes).to_string();
                if opts.trim {
                    line_str = line_str.trim_start().to_string();
                }

                let mut prefix = String::new();
                if opts.with_filename && !opts.heading {
                    if opts.color {
                        prefix.push_str(&format!("{}{}{}", color_path, path_formatted, color_reset));
                    } else {
                        prefix.push_str(&path_formatted);
                    }
                    prefix.push_str(&opts.field_context_separator);
                }
                if opts.line_number {
                    if opts.color {
                        prefix.push_str(&format!("{}{}{}", color_line, c.line_number, color_reset));
                    } else {
                        prefix.push_str(&c.line_number.to_string());
                    }
                    prefix.push_str(&opts.field_context_separator);
                }

                let line_out = format!("{}{}\n", prefix, line_str);
                out.write_all(line_out.as_bytes())?;
                stats.bytes_printed += line_out.len();
            }
        }
    }

    Ok(())
}

pub fn print_summary<W: Write>(
    out: &mut W,
    opts: &PrinterOptions,
    stats: &OverallStats,
    total_duration: Duration,
) -> io::Result<()> {
    if opts.json {
        let summary_evt = JsonEvent::Summary(JsonSummaryData {
            elapsed_total: JsonElapsed::new(total_duration),
            stats: JsonStats {
                elapsed: JsonElapsed::new(total_duration),
                searches: stats.searches,
                searches_with_match: stats.searches_with_match,
                bytes_searched: stats.bytes_searched,
                bytes_printed: stats.bytes_printed,
                matched_lines: stats.matched_lines,
                matches: stats.matches,
            },
        });
        let line = serde_json::to_string(&summary_evt).unwrap() + "\n";
        out.write_all(line.as_bytes())?;
        return Ok(());
    }

    let summary = format!(
        "\n{} matches\n{} matched lines\n{} files contained matches\n{} files searched\n{} bytes printed\n{} bytes searched\n{:.6} seconds spent searching\n{:.6} seconds\n",
        stats.matches,
        stats.matched_lines,
        stats.searches_with_match,
        stats.searches,
        stats.bytes_printed,
        stats.bytes_searched,
        total_duration.as_secs_f64(),
        total_duration.as_secs_f64()
    );
    out.write_all(summary.as_bytes())?;
    Ok(())
}
