fn main() {
    let start_time = Instant::now();
    let args = config::get_effective_args();

    let mut app = cli::build_cli();
    let matches = match app.try_get_matches_from_mut(args) {
        Ok(m) => m,
        Err(e) => {
            let err_str = e.to_string();
            if e.kind() == clap::error::ErrorKind::DisplayHelp {
                let _ = app.print_help();
                println!();
                exit(0);
            }
            if e.kind() == clap::error::ErrorKind::DisplayVersion {
                println!("ripgrep 14.1.1 (rev 41bff5fc54)");
                exit(0);
            }

            let msg = err_str.lines().next().unwrap_or("error parsing flags");
            eprintln!("rg: {}", msg);
            exit(2);
        }
    };

    // Check version flags
    if matches.get_flag("version_short") {
        println!("ripgrep 14.1.1 (rev 41bff5fc54)");
        exit(0);
    }
    if matches.get_flag("version_long") {
        println!("ripgrep 14.1.1 (rev 41bff5fc54)\n\nfeatures:-pcre2\nsimd(compile):+SSE2,-SSSE3,-AVX2\nsimd(runtime):+SSE2,+SSSE3,+AVX2\n\nPCRE2 is not available in this build of ripgrep.");
        exit(0);
    }

    // Check help flags
    if matches.get_flag("help_short") {
        let _ = app.print_help();
        println!();
        exit(0);
    }
    if matches.get_flag("help_long") {
        let _ = app.print_long_help();
        println!();
        exit(0);
    }

    // Check PCRE2
    if matches.get_flag("pcre2-version") {
        println!("PCRE2 is not available in this build of ripgrep.");
        exit(1);
    }
    if matches.get_flag("pcre2") {
        eprintln!("rg: PCRE2 is not available in this build of ripgrep");
        exit(2);
    }

    // Check --generate
    if let Some(kind) = matches.get_one::<String>("generate") {
        if generate::print_completion(kind, app) {
            exit(0);
        } else {
            eprintln!("rg: unknown generate kind '{}'", kind);
            exit(2);
        }
    }

    // Check --type-list
    if matches.get_flag("type-list") {
        let mut builder = TypesBuilder::new();
        builder.add_defaults();

        if let Some(clears) = matches.get_many::<String>("type-clear") {
            for c in clears {
                builder.clear(c);
            }
        }
        if let Some(adds) = matches.get_many::<String>("type-add") {
            for a in adds {
                let _ = builder.add_def(a);
            }
        }

        if let Ok(types) = builder.build() {
            for def in types.definitions() {
                let globs: Vec<&str> = def.globs().iter().map(|s| s.as_str()).collect();
                println!("{}: {}", def.name(), globs.join(", "));
            }
        }
        exit(0);
    }

