        only_matching: matches.get_flag("only-matching"),
        replace: matches.get_one::<String>("replace").cloned(),
        passthru: matches.get_flag("passthru"),
        trim: matches.get_flag("trim"),
        max_columns: matches
            .get_one::<String>("max-columns")
